uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_halBufA;
float4 amzSample_halBufA(float2 uv) { return float4(amzt_halBufA.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
uniform shader amzt_halBufB;
float4 amzSample_halBufB(float2 uv) { return float4(amzt_halBufB.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
uniform shader amzt_halBufC;
float4 amzSample_halBufC(float2 uv) { return float4(amzt_halBufC.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
uniform shader amzt_halBufD;
float4 amzSample_halBufD(float2 uv) { return float4(amzt_halBufD.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_halBufA(uv);if(tex==2) return amzSample_halBufB(uv);if(tex==3) return amzSample_halBufC(uv);if(tex==4) return amzSample_halBufD(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_halStrength;
uniform float amzp_halRadius;
uniform float amzp_halSoftness;
uniform float amzp_halThreshold;
uniform float amzp_halKnee;
uniform float amzp_halGamma;
layout(color) uniform half4 amzp_halColor;
uniform float amzp_halColorStr;
uniform float amzp_useSourceColor;
uniform float amzp_filmStock;
uniform float amzp_innerWeight;
uniform float amzp_outerWeight;
uniform float amzp_spreadRatio;
uniform float amzp_redBleed;
uniform float amzp_greenBleed;
uniform float amzp_blueBleed;
uniform float amzp_edgeHalStr;
uniform float amzp_edgeHalRadius;
uniform float amzp_gateWeave;
uniform float amzp_gateFlicker;
uniform float amzp_saturation;
uniform float amzp_warmth;
uniform float amzp_fadedFilm;
uniform float amzp_blendMode;
uniform float amzp_quality;
uniform float amzp_halOnly;
uniform float amzp_ditherAmt;
uniform float amzp_globalMix;
    float lum(float3 c) {
        return dot(c, float3(0.2126, 0.7152, 0.0722));
    }
    float3 srgbToLinear(float3 s) {
        float3 lo = s / 12.92;
        float3 hi = pow((s + 0.055) / 1.055, float3(2.4));
        return mix(lo, hi, step(float3(0.04045), s));
    }
    float3 linearToSrgb(float3 l) {
        float3 lo = l * 12.92;
        float3 hi = 1.055 * pow(max(l, 0.0), float3(1.0 / 2.4)) - 0.055;
        return mix(lo, hi, step(float3(0.0031308), l));
    }
    float noiseHash(float2 p) {
        float3 p3 = fract(float3(p.xyx) * 0.1031);
        p3 += dot(p3, p3.yzx + 33.33);
        return fract((p3.x + p3.y) * p3.z);
    }
    float getTaps(float q) {
        if (q < 1.5) return 8.0;
        if (q < 2.5) return 14.0;
        return 20.0;
    }
    float4 blurPass(int tex, float2 texOff, float2 st, float numPx) {
        if (numPx <= 0.0) return amzTexture(tex, st);
        float sigma = numPx / 2.14596602;
        sigma = max(sigma, 0.00001);
         float3 ig;
        ig.x = 1.0 / (sqrt(2.0 * 3.14159265359) * sigma);
        ig.y = exp(-0.5 / (sigma * sigma));
        ig.z = ig.y * ig.y;
        float4 avg = amzTexture(tex, st) * ig.x;
        float cSum = ig.x;
        for (float i = 1.0; i <= 256.0; i += 2.0) {
            if (i > numPx) break;
            ig.xy *= ig.yz;
            cSum += 2.0 * ig.x;
            float w0 = ig.x;
            ig.xy *= ig.yz;
            cSum += 2.0 * ig.x;
            float w1 = ig.x;
            float wL = w0 + w1;
            float oL = (i * w0 + (i + 1.0) * w1) / max(wL, 0.00001);
            avg += amzTexture(tex, clamp(st - oL * texOff, 0.0, 1.0)) * wL;
            avg += amzTexture(tex, clamp(st + oL * texOff, 0.0, 1.0)) * wL;
        }
        return avg / max(cSum, 0.00001);
    }
    float3 getFilmStockColor(float stock) {
        if (stock < 1.5) return float3(1.0);
        if (stock < 2.5) return float3(1.0, 0.15, 0.05);
        if (stock < 3.5) return float3(0.9, 0.2, 0.08);
        if (stock < 4.5) return float3(1.0, 0.12, 0.03);
        return float3(1.0, 0.3, 0.15);
    }
    float3 getFilmStockBleed(float stock) {
        if (stock < 1.5) return float3(amzp_redBleed, amzp_greenBleed, amzp_blueBleed);
        if (stock < 2.5) return float3(1.0, 0.25, 0.08);
        if (stock < 3.5) return float3(0.9, 0.3, 0.1);
        if (stock < 4.5) return float3(1.0, 0.2, 0.05);
        return float3(1.0, 0.4, 0.2);
    }
    void amzRender() {
        float2 uv = amzScreenNorm();
        float taps = getTaps(float(int(amzp_quality)));
        float fs = float(int(amzp_filmStock));
        float r1 = amzp_halRadius * 0.5;
        float r2 = amzp_halRadius * amzp_spreadRatio * 0.5;
        if (amzPass == 0) {
            float4 src = amzTexture(0, uv);
            float3 rgb = max(src.rgb, 0.0);
            float3 lin = srgbToLinear(rgb);
            float brightness = lum(lin);
            brightness = pow(max(brightness, 0.0), amzp_halGamma);
            float knee = max(amzp_halKnee, 0.00001);
            float edge = brightness - amzp_halThreshold + knee;
            edge = clamp(edge / (2.0 * knee), 0.0, 1.0);
            edge *= edge;
            float mask = max(edge, max(brightness - amzp_halThreshold, 0.0));
            mask = mask / max(brightness, 0.00001);
            float3 extracted = rgb * mask;
            float3 hColor;
            if ((amzp_useSourceColor>0.5)) {
                hColor = extracted;
            } else {
                float3 stockColor = getFilmStockColor(fs);
                float3 userColor = amzp_halColor.rgb;
                hColor = (fs < 1.5) ? userColor : stockColor;
                float extractLum = lum(extracted);
                hColor = hColor * extractLum * 2.0;
                hColor = mix(extracted, hColor, amzp_halColorStr);
            }
            float3 bleed = (fs < 1.5) ? float3(amzp_redBleed, amzp_greenBleed, amzp_blueBleed) : getFilmStockBleed(fs);
            hColor *= bleed;
            if (amzp_edgeHalStr > 0.00001) {
                float2 px = 1.0 / getTexSize((screen.zw/1.0));
                float edgeR = amzp_edgeHalRadius;
                float c = lum(srgbToLinear(rgb));
                float t = lum(srgbToLinear(max(amzTexture(0, clamp(uv + float2(0.0, -px.y * edgeR), 0.0, 1.0)).rgb, 0.0)));
                float b = lum(srgbToLinear(max(amzTexture(0, clamp(uv + float2(0.0, px.y * edgeR), 0.0, 1.0)).rgb, 0.0)));
                float l = lum(srgbToLinear(max(amzTexture(0, clamp(uv + float2(-px.x * edgeR, 0.0), 0.0, 1.0)).rgb, 0.0)));
                float r = lum(srgbToLinear(max(amzTexture(0, clamp(uv + float2(px.x * edgeR, 0.0), 0.0, 1.0)).rgb, 0.0)));
                float edgeDetect = abs(t - b) + abs(l - r);
                float edgeMask = smoothstep(0.1, 0.5, edgeDetect);
                hColor += extracted * edgeMask * amzp_edgeHalStr * 0.5;
            }
            amzOutput = float4(hColor, src.a);
            return;
        }
        if (amzPass == 1) {
            float2 to = float2(1.0 / getTexSize((screen.zw/2.0)).x, 0.0);
            float ks = r1 * (taps / 10.0);
            amzOutput = blurPass(1, to, uv, ks);
            return;
        }
        if (amzPass == 2) {
            float2 to = float2(0.0, 1.0 / getTexSize((screen.zw/2.0)).y);
            float ks = r1 * (taps / 10.0);
            amzOutput = blurPass(2, to, uv, ks);
            return;
        }
        if (amzPass == 3) {
            float2 to = float2(1.0 / getTexSize((screen.zw/2.0)).x, 0.0);
            float ks = r2 * (taps / 10.0);
            amzOutput = blurPass(1, to, uv, ks);
            return;
        }
        float4 src = amzTexture(0, uv);
        float3 baseRGB = max(src.rgb, 0.0);
        if (amzp_gateWeave > 0.00001) {
            float wv = amzp_gateWeave * 0.003;
            float offX = sin(time * 7.0 + uv.y * 3.0) * wv;
            float offY = cos(time * 5.0 + uv.x * 2.0) * wv * 0.5;
            float2 weaveUV = clamp(uv + float2(offX, offY), 0.0, 1.0);
            baseRGB = max(amzTexture(0, weaveUV).rgb, 0.0);
        }
        if (amzp_gateFlicker > 0.00001) {
            float flick = 1.0 + (noiseHash(float2(time * 15.0, 0.0)) - 0.5) * amzp_gateFlicker * 0.15;
            baseRGB *= flick;
        }
        float3 innerHal = max(amzTexture(3, uv).rgb, 0.0);
        float3 outerHal = max(amzTexture(4, uv).rgb, 0.0);
        float3 halLin = srgbToLinear(innerHal) * amzp_innerWeight
                    + srgbToLinear(outerHal) * amzp_outerWeight;
        halLin = mix(srgbToLinear(innerHal), halLin, amzp_halSoftness);
        halLin *= amzp_halStrength;
        halLin = 1.0 - exp(-halLin * 3.0);
        float3 halSRGB = linearToSrgb(max(halLin, 0.0));
        if ((amzp_halOnly>0.5)) {
            amzOutput = float4(clamp(halSRGB, 0.0, 1.0), 1.0);
            return;
        }
        float3 baseLin = srgbToLinear(baseRGB);
        float3 halBlend = srgbToLinear(max(halSRGB, 0.0));
        float3 comp;
        float bm = float(int(amzp_blendMode));
        if (bm < 1.5) {
            comp = baseLin + halBlend;
        } else if (bm < 2.5) {
            comp = srgbToLinear(1.0 - (1.0 - baseRGB) * (1.0 - clamp(halSRGB, 0.0, 1.0)));
        } else {
            float3 gC = clamp(halSRGB, 0.0, 1.0);
            float3 r;
            r.r = (gC.r<0.5) ? 2.0*baseRGB.r*gC.r+baseRGB.r*baseRGB.r*(1.0-2.0*gC.r) : 2.0*baseRGB.r*(1.0-gC.r)+sqrt(max(baseRGB.r,0.0))*(2.0*gC.r-1.0);
            r.g = (gC.g<0.5) ? 2.0*baseRGB.g*gC.g+baseRGB.g*baseRGB.g*(1.0-2.0*gC.g) : 2.0*baseRGB.g*(1.0-gC.g)+sqrt(max(baseRGB.g,0.0))*(2.0*gC.g-1.0);
            r.b = (gC.b<0.5) ? 2.0*baseRGB.b*gC.b+baseRGB.b*baseRGB.b*(1.0-2.0*gC.b) : 2.0*baseRGB.b*(1.0-gC.b)+sqrt(max(baseRGB.b,0.0))*(2.0*gC.b-1.0);
            comp = srgbToLinear(r);
        }
        float3 fin = linearToSrgb(max(comp, 0.0));
        if (abs(amzp_saturation - 1.0) > 0.00001) {
            float fl = lum(fin);
            fin = mix(float3(fl), fin, amzp_saturation);
        }
        if (abs(amzp_warmth) > 0.00001) {
            fin.r += amzp_warmth * 0.06;
            fin.b -= amzp_warmth * 0.04;
        }
        if (amzp_fadedFilm > 0.00001) {
            fin = fin * (1.0 - amzp_fadedFilm * 0.15) + amzp_fadedFilm * 0.1;
            float fl = lum(fin);
            fin = mix(fin, float3(fl), amzp_fadedFilm * 0.2);
        }
        if (amzp_ditherAmt > 0.00001) {
            float2 px = floor(getTexSize((screen.zw/1.0)) * uv);
            float n1 = fract(sin(dot(px, float2(12.9898, 78.233))) * 43758.5453);
            float n2 = fract(sin(dot(px, float2(24.123, 17.321))) * 12345.6789);
            float n3 = fract(sin(dot(px, float2(93.989, 67.345))) * 98765.4321);
            fin += (float3(n1, n2, n3) - 0.5) * amzp_ditherAmt;
        }
        fin = mix(baseRGB, fin, amzp_globalMix);
        fin = clamp(fin, 0.0, 1.0);
        amzOutput = float4(fin, src.a);
    }

half4 main(float2 coord) { amzCoord=coord*2.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

