            float offX = sin(time * 7.0 + uv.y * 3.0) * wv;
            float offY = cos(time * 5.0 + uv.x * 2.0) * wv * 0.5;
            float2 weaveUV = clamp(uv + float2(offX, offY), 0.0, 1.0);
            baseRGB = max(amzTexture(0, weaveUV).rgb, 0.0);
        }
        if (amzp_gateFlicker > 0.00001) {
            float flick = 1.0 + (noiseHash(float2(time * 15.0, 0.0)) - 0.5) * amzp_gateFlicker * 0.15;
            baseRGB *= flick;
        }
        float3 innerHal = max(amzTexture(3, uv).rgb, 0.0);
        float3 outerHal = max(amzTexture(4, uv).rgb, 0.0);
        float3 halLin = srgbToLinear(innerHal) * amzp_innerWeight
                    + srgbToLinear(outerHal) * amzp_outerWeight;
        halLin = mix(srgbToLinear(innerHal), halLin, amzp_halSoftness);
        halLin *= amzp_halStrength;
        halLin = 1.0 - exp(-halLin * 3.0);
        float3 halSRGB = linearToSrgb(max(halLin, 0.0));
        if ((amzp_halOnly>0.5)) {
            amzOutput = float4(clamp(halSRGB, 0.0, 1.0), 1.0);
            return;
        }
        float3 baseLin = srgbToLinear(baseRGB);
        float3 halBlend = srgbToLinear(max(halSRGB, 0.0));
        float3 comp;
        float bm = float(int(amzp_blendMode));
        if (bm < 1.5) {
            comp = baseLin + halBlend;
        } else if (bm < 2.5) {
            comp = srgbToLinear(1.0 - (1.0 - baseRGB) * (1.0 - clamp(halSRGB, 0.0, 1.0)));
        } else {
            float3 gC = clamp(halSRGB, 0.0, 1.0);
            float3 r;
            r.r = (gC.r<0.5) ? 2.0*baseRGB.r*gC.r+baseRGB.r*baseRGB.r*(1.0-2.0*gC.r) : 2.0*baseRGB.r*(1.0-gC.r)+sqrt(max(baseRGB.r,0.0))*(2.0*gC.r-1.0);
            r.g = (gC.g<0.5) ? 2.0*baseRGB.g*gC.g+baseRGB.g*baseRGB.g*(1.0-2.0*gC.g) : 2.0*baseRGB.g*(1.0-gC.g)+sqrt(max(baseRGB.g,0.0))*(2.0*gC.g-1.0);
            r.b = (gC.b<0.5) ? 2.0*baseRGB.b*gC.b+baseRGB.b*baseRGB.b*(1.0-2.0*gC.b) : 2.0*baseRGB.b*(1.0-gC.b)+sqrt(max(baseRGB.b,0.0))*(2.0*gC.b-1.0);
            comp = srgbToLinear(r);
        }
        float3 fin = linearToSrgb(max(comp, 0.0));
        if (abs(amzp_saturation - 1.0) > 0.00001) {
            float fl = lum(fin);
            fin = mix(float3(fl), fin, amzp_saturation);
        }
        if (abs(amzp_warmth) > 0.00001) {
            fin.r += amzp_warmth * 0.06;
            fin.b -= amzp_warmth * 0.04;
        }
        if (amzp_fadedFilm > 0.00001) {
            fin = fin * (1.0 - amzp_fadedFilm * 0.15) + amzp_fadedFilm * 0.1;
            float fl = lum(fin);
            fin = mix(fin, float3(fl), amzp_fadedFilm * 0.2);
        }
        if (amzp_ditherAmt > 0.00001) {
            float2 px = floor(getTexSize((screen.zw/1.0)) * uv);
            float n1 = fract(sin(dot(px, float2(12.9898, 78.233))) * 43758.5453);
            float n2 = fract(sin(dot(px, float2(24.123, 17.321))) * 12345.6789);
            float n3 = fract(sin(dot(px, float2(93.989, 67.345))) * 98765.4321);
            fin += (float3(n1, n2, n3) - 0.5) * amzp_ditherAmt;
        }
        fin = mix(baseRGB, fin, amzp_globalMix);
        fin = clamp(fin, 0.0, 1.0);
        amzOutput = float4(fin, src.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
